import{_ as e,o as n,c as i,a0 as t}from"./chunks/framework.dDzXfurR.js";const u=JSON.parse('{"title":"springcloud-day04","description":"学习springcloud","frontmatter":{"title":"springcloud-day04","description":"学习springcloud","date":"2026-10-09T00:00:00.000Z","tags":["java","后端"]},"headers":[],"relativePath":"posts/springcloud-day04.md","filePath":"posts/springcloud-day04.md","lastUpdated":1791736239000}'),s={name:"posts/springcloud-day04.md"};function r(l,a,o,h,d,c){return n(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="微服务保护和分布式事务" tabindex="-1">微服务保护和分布式事务 <a class="header-anchor" href="#微服务保护和分布式事务" aria-label="Permalink to &quot;微服务保护和分布式事务&quot;">​</a></h1><h2 id="微服务保护" tabindex="-1">微服务保护 <a class="header-anchor" href="#微服务保护" aria-label="Permalink to &quot;微服务保护&quot;">​</a></h2><p>雪崩问题 --由于请求处理速度小于请求速度</p><p>方法：请求限流、熔断 线程隔离 fallback</p><p>工具: sentine</p><h2 id="分布式事务" tabindex="-1">分布式事务 <a class="header-anchor" href="#分布式事务" aria-label="Permalink to &quot;分布式事务&quot;">​</a></h2><p>起因，不同功能的服务作为统一的事务</p><p>方法： seata</p><p>模式: XT AT</p><h1 id="mq异步调用" tabindex="-1">MQ异步调用 <a class="header-anchor" href="#mq异步调用" aria-label="Permalink to &quot;MQ异步调用&quot;">​</a></h1><h2 id="work-queues" tabindex="-1">Work Queues <a class="header-anchor" href="#work-queues" aria-label="Permalink to &quot;Work Queues&quot;">​</a></h2><p>defual方式: 几个线程平均分配</p><p>通过修改 <code>preFetch:1</code> 的方式 &quot;能者多劳&quot;</p><h2 id="交换机" tabindex="-1">交换机 <a class="header-anchor" href="#交换机" aria-label="Permalink to &quot;交换机&quot;">​</a></h2><h3 id="fanout-广播-所有队列都能收到" tabindex="-1">Fanout(广播) --- 所有队列都能收到 <a class="header-anchor" href="#fanout-广播-所有队列都能收到" aria-label="Permalink to &quot;Fanout(广播) --- 所有队列都能收到&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/SFoneis/blog-images@main/images/20261009173542397.png" alt=""></p><h3 id="direct-对应的bindingkey可以收到" tabindex="-1">Direct --- 对应的bindingKey可以收到 <a class="header-anchor" href="#direct-对应的bindingkey可以收到" aria-label="Permalink to &quot;Direct --- 对应的bindingKey可以收到&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/SFoneis/blog-images@main/images/20261009173444035.png" alt=""></p><h3 id="topic-可以添加通配符比如-china-new-china" tabindex="-1">Topic --- 可以添加通配符比如(china.new china.#) <a class="header-anchor" href="#topic-可以添加通配符比如-china-new-china" aria-label="Permalink to &quot;Topic ---  可以添加通配符比如(china.new china.#)&quot;">​</a></h3><h1 id="mq的异步传输的可靠性" tabindex="-1">MQ的异步传输的可靠性 <a class="header-anchor" href="#mq的异步传输的可靠性" aria-label="Permalink to &quot;MQ的异步传输的可靠性&quot;">​</a></h1><h2 id="发送者" tabindex="-1">发送者 <a class="header-anchor" href="#发送者" aria-label="Permalink to &quot;发送者&quot;">​</a></h2><h3 id="发送者重连" tabindex="-1">发送者重连 <a class="header-anchor" href="#发送者重连" aria-label="Permalink to &quot;发送者重连&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/SFoneis/blog-images@main/images/20261009182403943.png" alt=""></p><h3 id="发送者却惹" tabindex="-1">发送者却惹 <a class="header-anchor" href="#发送者却惹" aria-label="Permalink to &quot;发送者却惹&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/SFoneis/blog-images@main/images/20261009182448776.png" alt=""></p><h2 id="mq" tabindex="-1">MQ <a class="header-anchor" href="#mq" aria-label="Permalink to &quot;MQ&quot;">​</a></h2><h3 id="数据持久化" tabindex="-1">数据持久化 <a class="header-anchor" href="#数据持久化" aria-label="Permalink to &quot;数据持久化&quot;">​</a></h3><p>通过三层持久化(路由，队列，消息)</p><h3 id="lazy-queues" tabindex="-1">Lazy Queues <a class="header-anchor" href="#lazy-queues" aria-label="Permalink to &quot;Lazy Queues&quot;">​</a></h3><p>在rbitMQ 3.12之后所有的队列默认为Lazy Queues (不仔细观看，到时候遇到了再说)</p><h2 id="消费者" tabindex="-1">消费者 <a class="header-anchor" href="#消费者" aria-label="Permalink to &quot;消费者&quot;">​</a></h2><h3 id="消费者确认机制" tabindex="-1">消费者确认机制 <a class="header-anchor" href="#消费者确认机制" aria-label="Permalink to &quot;消费者确认机制&quot;">​</a></h3><p>在<code>simple: acknowlege-mode : auto</code>none 关闭 manual 手动</p><h3 id="失败重试机制" tabindex="-1">失败重试机制 <a class="header-anchor" href="#失败重试机制" aria-label="Permalink to &quot;失败重试机制&quot;">​</a></h3><p>通过</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>retry:</span></span>
<span class="line"><span>    enable: true 是否开启</span></span>
<span class="line"><span>    initial-interval: 1000ms  初始失败间隔时间</span></span>
<span class="line"><span>    multiplier: 1  失败间隔时间倍数</span></span>
<span class="line"><span>    max-attempts: 3 最大重试次数</span></span>
<span class="line"><span>    stateless: true 无状态 false 有状态 如果业务中包含事务，这里false</span></span></code></pre></div><h3 id="业务幂等性" tabindex="-1">业务幂等性 <a class="header-anchor" href="#业务幂等性" aria-label="Permalink to &quot;业务幂等性&quot;">​</a></h3><p>通过业务判断</p><h3 id="消息延迟" tabindex="-1">消息延迟 <a class="header-anchor" href="#消息延迟" aria-label="Permalink to &quot;消息延迟&quot;">​</a></h3><h2 id="delayed-message" tabindex="-1">Delayed Message <a class="header-anchor" href="#delayed-message" aria-label="Permalink to &quot;Delayed Message&quot;">​</a></h2><p>通过插件的方式，做到延迟消息的效果</p>`,41)])])}const m=e(s,[["render",r]]);export{u as __pageData,m as default};
